#!/bin/bash
# Список НАШИХ доработок под мост инструментов + сверка после обновления платформы.
#
# КЛАССЫ (по разбору Вениамина 22.08.2026; легенда приведена к ПРАКТИКЕ 26.09.2026 — находка Вениамина 20:06Z).
# 🔴 БУКВА — МЕТКА ДЛЯ ЧЕЛОВЕКА, КОД ЕЁ НЕ РАЗЛИЧАЕТ: сумма, эталон и --check одни для всех классов (циклы FILES/LINKS
#   ниже букву печатают, но по ней не ветвятся). Риск несёт МЕСТО файла, а не буква. Счёт — строки списка на
#   26.09.2026 22:3xZ: 490 файлов (FILES) + 5 ссылок (LINKS) = 495.
#   A 141 — наш файл вне дерева приложения        → обновление платформы переживёт.
#           Где: dorabotki 63 (корень 62, stendy 1) · /opt/agent-plugins 50 · /opt/iskra/plugins 22 (1 — ссылка)
#           · workspace вне dorabotki 4 · /usr/local 2.
#   B  22 — наш конфиг/пресет/ссылка в .dsh АГЕНТА → переживёт; риск тихого затенения по id.
#           Где: свой /opt/iskra/.dsh 11 (3 — ссылки) · чужие /opt/<агент>/.dsh 11 (профили других узлов).
#   C   0 — правка в дереве приложения            → ЗАТРЁТСЯ МОЛЧА. Стоп-класс: строк нет и быть не должно;
#           ловится ОБХОДОМ дерева (раздел «КЛАСС C» ниже), а не буквой.
#   D  70 — ИСХОДНО «правка/файл в чужом шлюзе»   → затрётся при обновлении ШЛЮЗА. Так — только 8 (/opt/claude-oauth).
#           НА ПРАКТИКЕ D — наши инструменты и стенды в dorabotki: 60 (корень 29, stendy 24, omega-*/pravka.diff 5,
#           pribory-zamera 2) + 2 записки в workspace. Для этих 62 риск как у A: переживут и платформу, и шлюз.
#   E 261 — наш файл в СИСТЕМНОМ каталоге         → обновление платформы переживёт; обновление ОС/поставки может
#           затереть или ПЕРЕКРЫТЬ файлом с бо́льшим номером. Где: /etc 129 (1 — ссылка) · /usr/local 77
#           · /opt/omega site-packages 6 (правки поставки OMEGA — затрёт `pip install`) · /opt/sage-corrector 3
#           · /opt/agent-plugins 3 · /opt/agent-skills-local 2 · .dsh 1 · /opt/iskra 1.
#           И dorabotki 39 — наши инструменты и стенды СИСТЕМНЫХ предметов (vypusk-tegom, stend-needrestart, …):
#           для них риск как у A.
#   Q   1 — документ процедур (strahovki/KUDA-KLADU.txt); основной разряд Q — обходом (раздел «РАЗРЯД Q» ниже).
#   ⇒ В dorabotki буквы A/D/E риска НЕ различают: все три — «наш файл в workspace» (162 строки: A 63 + D 60 + E 39). Смена буквы у
#     прежней строки меняет строку эталона и ничего не проверяет — прежние не переписываются.
#   ПРАВИЛО для НОВЫХ строк (слово Забавы 26.09.2026 22:3xZ): наш файл в dorabotki (инструмент, стенд, записка,
#     патч поставки) — класс A. D — только файл в чужом шлюзе, E — только файл в системном каталоге.
#
# 🔴 ЗАЧЕМ ДОБАВЛЕН КЛАСС E (24.08.2026, слово главной). Наши правки в /etc до
# этого держал ОДИН учёт — реестр вмешательств. Одна опора неотличима от нуля
# опор в тот день, когда она соврёт: проверка реестра сама может оказаться
# негодной (мы ловили такое трижды), и тогда сказать об этом некому. Здесь
# опора вторая и другого рода — не «выполняется ли условие», а «тот ли байт
# лежит».
# ГРАНИЦА КЛАССА E, названная прямо: сумма файла НЕ доказывает, что правка
# ДЕЙСТВУЕТ. Для needrestart и apt порядок чтения каталога решает всё —
# файл с бо́льшим номером перезатирает наш при целом нашем файле и сходящейся
# сумме (замерено 24.08 на живом needrestart). Это ловит только реестр
# вмешательств своей проверкой действия. Две опоры отвечают на разные вопросы,
# и подменять одну другой нельзя.
#
# ПАРА БОЙ/ЗАГОТОВКА (.bridge у gateway.mjs и jsonschema-to-zod.mjs) СНЯТА 23.09.2026 (A-N-723):
# источник выпуска шлюза — дерево dsh-plugins и метка; .bridge был дублем, который догоняли руками
# на каждом монтаже. Заготовки убраны в страховку, сверка боя с деревом — сторож выпуска и реестр.
#
# ЗАЧЕМ: после обновления платформы или шлюза сверить одним числом — цело или затёрто.
#   nashi-dorabotki.sh          — ТОЛЬКО печатает таблицу, эталон НЕ трогает
#   nashi-dorabotki.sh --check  — сверяет с манифестом, код 1 при расхождении
#   nashi-dorabotki.sh --save   — ПОКАЗЫВАЕТ, что узаконит, и не пишет (код 3)
#   nashi-dorabotki.sh --save --izmenenij N — пишет, если меняется ровно N строк
#
# 🔴 22.08.2026: раньше печать таблицы ЗАОДНО переписывала эталон. Значит любой
# просмотр обнулял способность --check заметить подмену: посмотрел список —
# и сверять стало не с чем, а --check после этого всегда зелёный. Имя режима
# говорило «показать», действие было «переписать». Разделено: пишет только --save.
#
# ГРАНИЦЫ. Ловит: пропажу файла, изменение содержимого, обрыв ссылки.
#   НЕ ловит: изменения ВНУТРИ дерева приложения (там наших файлов нет — это и проверяется),
#   и правку, сделанную нами же намеренно (после своей правки манифест перезаписать).
#   Ничего не чинит сам и никогда не восстанавливает — только сообщает.
#
# 🔴 ЧЕГО ЭТОТ УЧЁТ НЕ ЛОВИТ — названо прямо, чтобы зелёный не читался шире (28.08.2026):
#   1. Верность самого списка. Всё, чего в списке нет, для учёта не существует, и об этом
#      он не скажет НИКОГДА: список задан здесь явно, новый файл в него сам не попадает.
#      Так манифесты профилей и три инструмента прожили вне обеих опор — учёт был зелёным
#      не потому что цело, а потому что не видит. Ловится только счётом по классу, не чтением.
#   2. Действует ли правка. Сумма отвечает «тот ли байт лежит»; действие — реестр вмешательств.
#   3. Свою же намеренную правку (после неё эталон сводится, и это часть правки, а не потом).
#   4. Себя. manifest.txt не мерится ничем — это точка разрыва цикла, вносить его в реестр
#      вмешательств НЕЛЬЗЯ (взаимное измерение не сходится никогда, stend-atsiklichnosti.sh).

set -u

# 🔴 ПОРЯДОК СОРТИРОВКИ ЗАВИСЕЛ ОТ ТОГО, ЧЬЕЙ РУКОЙ ЗАПУЩЕНО (измерено 23.08.2026).
# Манифест сортируется `sort`, а `sort` берёт правило сравнения из локали. Эталон
# записывался из моей оболочки (LANG=ru_RU.UTF-8), где «-» и «.» при сравнении почти
# не весят, а --check из-под таймера идёт с пустым окружением, то есть в локали C —
# и те же самые строки выстраивались иначе. Итог: --check краснел на ИСПРАВНОЙ машине,
# показывая пары «-D|…» и «+D|…» с ОДИНАКОВЫМ содержимым. Ровно тот класс, что и
# `sudo -l` без -U: субъект проверки подставляется окружением, и разные руки получают
# разную картину одной машины.
# Здесь локаль задана явно и в самом скрипте — чтобы порядок не зависел ни от чьей руки.
# C.UTF-8, а не C: сравнение то же самое (проверено на этом манифесте), но многобайтные
# буквы не рвутся при обрезке — сосед на этом горел в сторожа машины.
# ГДЕ НЕ ДЕЙСТВУЕТ: на уже записанный эталон. Манифест, сохранённый до этой правки,
# лежит в старом порядке; его надо один раз пересортировать (набор строк при этом
# не меняется — это доказывается сравнением множеств, а не доверием).
export LC_ALL=C.UTF-8

# B-N-1227: npm не должен брать чужой HOME от sudo без -H.
# HOME передаётся также канону P и заморозке: они вызывают npm внутри себя.
_nashi_uid=$(/usr/bin/id -u)
if ! _nashi_passwd=$(/usr/bin/getent passwd "$_nashi_uid"); then
    echo "🔴 СЛЕПОТА: getent passwd для uid $_nashi_uid не отдал дом" >&2
    exit 1
fi
NASHI_HOME=$(printf '%s\n' "$_nashi_passwd" | cut -d: -f6)
if [[ "$NASHI_HOME" != /* || "$NASHI_HOME" == *$'\n'* ]]; then
    echo "🔴 СЛЕПОТА: getent passwd для uid $_nashi_uid отдал негодный дом" >&2
    exit 1
fi

MANIFEST="${MANIFEST:-/opt/iskra/workspace/dorabotki/manifest.txt}"
dubli_v_spiske() {
    # 🔴 ДУБЛИ ПУТЕЙ В СПИСКЕ (05.09.2026). Строка про stendy/stend-pered-podyomom.mjs
    # пролежала в списке ДВАЖДЫ: старая редакция описания (10 проб, В1–В8) и новая
    # (21 проба, В1–В11). Задвоение прошло молча, завысило счёт позиций на единицу,
    # а описания разошлись — читающий взял бы то, которое встретил первым.
    # КАК ВОЗНИКЛО: разряд «файлы вне учёта» кричал про КАТАЛОГ (искал имя каталога,
    # а в списке лежал путь до файла внутри), я прочла крик как «не учтён» и внесла
    # запись повторно. Верный симптом, ложный вывод — потому проверка здесь, не в памяти.
    # 🔴 И ЗОВЁТСЯ В ОБОИХ РЕЖИМАХ: первая редакция стояла только в ветке --save, а
    # дубль вреден всегда. Порчу я тогда гоняла через --check и получила «не краснеет» —
    # проба отвечала про свой режим, а не про предмет.
    # ГРАНИЦА: сверяются ПУТИ, не описания. Две строки на РАЗНЫЕ файлы с одинаковым
    # текстом этот разряд не поймает и ловить не должен.
    local dubli
    dubli=$(command grep -E "^[A-Z]\|" "$0" | cut -d"|" -f2 | sort | uniq -d)
    [ -z "$dubli" ] && return 0
    echo "🔴 ОДИН ПУТЬ В СПИСКЕ НЕСКОЛЬКО РАЗ — счёт позиций завышен, описания могут расходиться:"
    printf "   %s\n" $dubli
    return 0
}

MODE="${1:-list}"
ARG2="${2:-}"
ARG3="${3:-}"
# B-N-2025: 4 только по явному ключу, ручная сверка прежняя.
AVTO_MONTAZH=0
if [ "$MODE" = --check ]; then
  case "$#:${2:-}" in 1:) ;; 2:--avto-montazh) AVTO_MONTAZH=1 ;; *) echo 'ОТКАЗ: nashi-dorabotki.sh --check [--avto-montazh]' >&2; exit 2 ;; esac
fi
MO_HELPER=${MONTAZH_OKNO_BIN:-/usr/local/sbin/montazh-okno}
MO_STARTED=0
[ "$AVTO_MONTAZH" = 0 ] || MO_STARTED=$("$MO_HELPER" vremya 2>/dev/null) || MO_STARTED=0
# 🔴 ОБЛАСТЬ УЗАКОНИВАНИЯ БЕРЁТСЯ КЛЮЧОМ, А НЕ ПЕРЕМЕННОЙ ОКРУЖЕНИЯ. Переменная,
# оставшаяся от прошлого запуска, молча сузила бы область у следующего вызова, и
# «узаконено 2» читалось бы как «расхождений было 2». Ключ надо написать рукой.
# Форма: --save --izmenenij N --tolko <образец пути>
TOLKO=""
for ((i=1; i<=$#; i++)); do
  if [ "${!i}" = "--tolko" ]; then
    j=$((i+1)); TOLKO="${!j:-}"
    [ -z "$TOLKO" ] && { echo "🔴 --tolko без образца пути" >&2; exit 3; }
  fi
done

