# B-N-968 (25.09.2026, Аврора; класс A-N-919): ВСЁ временное — в одном каталоге, убирается целиком на ЛЮБОМ выходе.
# Было: trap чистил только $tmp, а $tmp.new/.new2/.now/.diff/.sdiff/.vne/.vnutri/.vsyo и C_ERR оставались в /tmp —
# замер: +2 (.vne/.vnutri) на каждый --save --tolko; на list/--check производных нет. EXIT-ловушку bash 5.2 зовёт и на
# SIGTERM/SIGINT (проверено), так что TERM/INT здесь — явный выход с кодом, а лечит главное — каталог целиком.
# Имена внутри прежние ($tmp.<суффикс>), меняется только то, где они лежат. От SIGKILL не спасает ничто.
VREM_KAT=$(mktemp -d) || { echo "СЛЕПОТА: не завести временный каталог" >&2; exit 1; }
trap 'rm -rf "$VREM_KAT"' EXIT; trap 'exit 143' TERM; trap 'exit 130' INT
tmp="$VREM_KAT/sverka"; : > "$tmp"
seen=0; missing=0

# B-N-961 (25.09.2026, Аврора; разбор Михалыча 20:03Z): суммы — ОДНИМ вызовом sudo на разряд, а не вызовом на файл.
# Было ≈475 вызовов на прогон (432 цели + 9 libexec + 27 пар + 5 ссылок + 2 обхода) × 116 прогонов/сут — 28,5% журнала
# sudo машины. Стало 5: список libexec, md5 целей и libexec разом, ссылки, sha256 пар, обход полноты пар (+stat на расхождение).
# Смысл прежний: сумма — от root; при отказе sudo читаемый файл досчитывается без sudo; чего нет — «НЕТ-ФАЙЛА».
# -z: путь целиком, без экранирования (пробелы, «\»); файл, которого нет, в выводе просто отсутствует.
# ⚠️ ЧЕГО НЕ ЛОВИТ ЛУЧШЕ ПРЕЖНЕГО: сумма снята на момент ОДНОГО вызова, а не каждого файла отдельно — окно то же, прогон.
LIBEXEC=/usr/local/libexec
spisok_L=$(sudo -n find "$LIBEXEC" -type f ! -name '*.bak*' 2>/dev/null | sort) || spisok_L=""
# Разряд Y (drop-in юнитов) — список здесь же, суммы тем же одним вызовом; устройство — у вывода разряда ниже.
DROPIN_KAT="${DROPIN_KAT:-/etc/systemd/system}"
CHUZHIE_Y='petrovich.service.d/30-porog-perebora-semejstv.conf|Петрович своей рукой («на моём узле»), его предмет
petrovich.service.d/50-full-access.conf|полный доступ узла Петровича (решение владельца 18.08), автор не назван — вне учёта до слова Забавы'
declare -A V_FILES=() V_CHUZHIE=()
while IFS='|' read -r cls path note; do case "${cls:-}" in \#*|'') continue;; esac; V_FILES["$path"]=1; done <<< "$FILES"
while IFS='|' read -r rel pr; do [ -n "$rel" ] && V_CHUZHIE["$rel"]=$pr; done <<< "$CHUZHIE_Y"
spisok_Y_vse=$(sudo -n find "$DROPIN_KAT" -mindepth 2 -maxdepth 2 -type f -path '*.d/*.conf' 2>/dev/null | sort) || spisok_Y_vse=""
spisok_Y=""; y_pod_E=0; y_chuzhih=0
while IFS= read -r f; do
    [ -z "$f" ] && continue
    if [ -n "${V_FILES["$f"]:-}" ]; then y_pod_E=$((y_pod_E+1)); continue; fi
    if [ -n "${V_CHUZHIE["${f#"$DROPIN_KAT"/}"]:-}" ]; then y_chuzhih=$((y_chuzhih+1)); continue; fi
    spisok_Y+="$f"$'\n'
done <<< "$spisok_Y_vse"
spisok_Y=${spisok_Y%$'\n'}
declare -A SUMMA_MD5=()
celi=()
while IFS='|' read -r cls path note; do case "${cls:-}" in \#*|'') continue;; esac; celi+=("$path"); done <<< "$FILES"
[ -n "$spisok_L" ] && while IFS= read -r f; do celi+=("$f"); done <<< "$spisok_L"
[ -n "$spisok_Y" ] && while IFS= read -r f; do celi+=("$f"); done <<< "$spisok_Y"
if [ "${#celi[@]}" -gt 0 ]; then
    while IFS= read -r -d '' rec; do SUMMA_MD5["${rec:34}"]=${rec:0:32}; done < <(sudo -n md5sum -z -- "${celi[@]}" 2>/dev/null)
fi

while IFS='|' read -r cls path note; do
    case "${cls:-}" in \#*|'') continue;; esac
    seen=$((seen+1))
    sum=${SUMMA_MD5["$path"]:-}
    if [ -z "$sum" ] && [ -r "$path" ]; then sum=$(md5sum "$path" 2>/dev/null | cut -d' ' -f1); fi
    if [ -n "$sum" ] && [ -n "${V_PRAVIT_AGENT["$path"]:-}" ]; then   # B-N-1281: хозяин и непустота вместо содержимого
        pa=$(sudo -n stat -c '%U %s' -- "$path" 2>/dev/null)
        if [ -z "$pa" ]; then sum="ПРАВИТ-АГЕНТ:СЛЕПОТА"
        else sum="ПРАВИТ-АГЕНТ:${pa%% *}"; [ "${pa##* }" = 0 ] && sum="$sum:ПУСТ"; fi
    fi
    if [ -n "$sum" ] && [ -n "${V_MENYAET_PROGRAMMA["$path"]:-}" ]; then   # B-N-1886: номер подписки 1–3 вне суммы
        if sudo -n sed -E 's#^GATEWAY_TOKEN_FILE=/etc/claude-oauth/token-podpiska-[123]$#GATEWAY_TOKEN_FILE=<podpiska-1-3>#' -- "$path" > "$tmp.mp" 2>/dev/null
        then sum="ПОДПИСКА-1-3:$(md5sum < "$tmp.mp" | cut -c1-32)"; else sum="ПОДПИСКА-1-3:СЛЕПОТА"; fi
        rm -f "$tmp.mp"
    fi
    if [ -z "$sum" ]; then sum="НЕТ-ФАЙЛА"; missing=$((missing+1)); fi
    printf '%s|%s|%s\n' "$cls" "$path" "$sum" >> "$tmp"
    [ "$MODE" = "list" ] && printf '%s  %-62s %s\n     %s\n' "$cls" "$path" "$sum" "$note"
done <<< "$FILES"

# B-N-961: цели ссылок — одним sudo; порядок вывода = порядок путей (пустое поле — не ссылка / нет файла).
ssylki=(); while IFS='|' read -r cls path; do [ -z "${cls:-}" ] && continue; ssylki+=("$path"); done <<< "$LINKS"
declare -A CEL_SSYLKI=()
if [ "${#ssylki[@]}" -gt 0 ]; then
    i=0; while IFS= read -r -d '' t; do CEL_SSYLKI["${ssylki[$i]}"]=$t; i=$((i+1)); done \
        < <(sudo sh -c 'for p do printf "%s\0" "$(readlink -- "$p")"; done' sh "${ssylki[@]}" 2>/dev/null)
fi
while IFS='|' read -r cls path; do
    [ -z "${cls:-}" ] && continue
    seen=$((seen+1))
    tgt=${CEL_SSYLKI["$path"]:-}
    if [ -z "$tgt" ]; then tgt="НЕТ-ССЫЛКИ"; missing=$((missing+1)); fi
    printf '%s|%s|-> %s\n' "$cls" "$path" "$tgt" >> "$tmp"
    [ "$MODE" = "list" ] && printf '%s  %-62s -> %s\n' "$cls" "$path" "$tgt"
done <<< "$LINKS"

# ═══ СОСТАВ ПАКЕТОВ — ОДНОЙ СУММОЙ НА ПАКЕТ, А НЕ ПЕРЕЧНЕМ ФАЙЛОВ ═══
#
# 🔴 ЗАЧЕМ (05.09.2026, лечение к разряду охвата). Под учётом было 59 файлов пакетов из 120:
# больше половины состава правилось МОЛЧА, а итог «СХОДИТСЯ, N позиций» читался как «всё под
# присмотром». Вносить недостающие файлы рукой значило бы завести перечень, который разойдётся
# с диском снова — ровно тот класс, который за сутки поймал меня трижды (маска стендов,
# канарейка условий, сводка состояния): перечень, записанный рукой, отвечает ПРО СЕБЯ.
# Потому здесь не перечень, а ОДНА строка на пакет: канон суммы предмета по всему составу.
# Появится новый файл, исчезнет старый, изменится любой — сумма другая, и это видно.
#
# ГДЕ НЕ ПРИМЕНЯЕТСЯ И ЧТО ЗНАЧИТ МОЛЧАНИЕ:
#   — область ровно /opt/iskra/plugins/*/ с package.json. Пакеты в других корнях
#     (/opt/agent-plugins, /opt/iskra/workspace) сюда НЕ входят: они ставятся из реестра
#     и правятся не моей рукой. Их молчание здесь ничего не значит;
#   — сумма считается КАНОНОМ (summa-predmeta) по составу тарбола, значит файл, не попавший
#     в тарбол, суммой не покрыт: не «под присмотром всё», а «под присмотром то, что поедет»;
#   — канон недоступен → строка «КАНОН-НЕ-ОТВЕТИЛ», это СЛЕПОТА и она видна, а не пропуск;
#   — расхождение исправных сумм узаконивается через --save, как и всё прочее.
#     Отказ канона — СЛЕПОТА и код 2 до сверки/записи эталона; пустую сумму узаконить нельзя.
# 🔴 ПУТЬ СМЕНЁН 05.09.2026, И ВОТ ПОЧЕМУ. Канон брался ИЗ НАБОРА, лежавшего в общем
# каталоге. Набор я в тот же день убрала (долг 111: внутри него ядро alpha.11 БЕЗ фильтра
# входа — заряжено на первую же ссылку), и вместе с ним исчезла опора СОБСТВЕННОГО учёта:
# все восемь пакетов разом дали «КАНОН-НЕ-ОТВЕТИЛ». Ссылки профилей на набор я проверила
# (их ноль), а кто опирается на него ВНУТРИ ИНСТРУМЕНТОВ — не проверила.
# КЛАСС: удаляя предмет, спрашивать надо не только «кто на него ссылается», но и «что из
# него берут». Второе не видно ни одной проверкой ссылок.
# Обе копии сверены перед сменой пути: md5 6f31943db82beddd у обеих, и на одном предмете
# дают одинаковый ответ (7d585ad81f5bc4d3, файлов 23) — то есть мера не подменена молча.
# 🔴 ОТ ЭТОГО ФАЙЛА ЗАВИСИТ ВЕСЬ РАЗРЯД ОХВАТА. Соберётесь убрать поставку — сначала
# перенесите канон, иначе учёт ослепнет по составу всех пакетов сразу.
# B-N-2048 (14.10): прежний канон читает только npm11; формат второго поля нового канона совместим.
KANON_SOSTAVA=/usr/local/bin/summa-predmeta-2
if [ ! -x "$KANON_SOSTAVA" ]; then
    echo "🔴 СЛЕПОТА РАЗРЯДА ОХВАТА: канона нет по пути $KANON_SOSTAVA"
    exit 2
fi
kanon_bed=0
# B-N-1353 (01.10): /opt/dsh-package-manager/<версия>/package — pnpm, который зовёт /usr/local/bin/pnpm. Смена версии = новый каталог:
# старая строка P пропадёт, новая появится — учёт покраснеет, и это нужное поведение (тихой подмены нет).
for d in /opt/iskra/plugins/*/ /opt/dsh-package-manager/*/package/; do
    [ -r "$d/package.json" ] || continue
    seen=$((seen+1))
    if ! ss=$(set -o pipefail; env HOME="$NASHI_HOME" "$KANON_SOSTAVA" "${d%/}" 2>/dev/null | awk '{print $2}') || [[ ! "$ss" =~ ^[0-9a-f]{16}$ ]]; then
        echo "СЛЕПОТА канона: ${d%/} — $KANON_SOSTAVA не дал одну 16-значную сумму" >&2
        ss="КАНОН-НЕ-ОТВЕТИЛ"; missing=$((missing+1)); kanon_bed=1
    fi
    printf 'P|%s|%s\n' "${d%/}" "$ss" >> "$tmp"
    [ "$MODE" = "list" ] && printf 'P  %-62s %s\n     состав пакета одной суммой (канон)\n' "${d%/}" "$ss"
done
[ "$kanon_bed" -eq 0 ] || exit 2

# РАЗРЯД Q: ДОКУМЕНТЫ ПРОЦЕДУР. Заведён 06.09.2026, долг 117.
# 🔴 ЗАЧЕМ. До этого каталог procedury/ не сверялся НИЧЕМ (grep 'procedury' по этому
# файлу давал 0 вхождений) и под git не лежит — пропажа или подмена документа проходила
# молча. Документ есть попытка вынести правило из переписки; несверяемый документ
# возвращает его туда же, только незаметнее.
# СОСТАВ БЕРЁТСЯ ОБХОДОМ КАТАЛОГА, НЕ СПИСКОМ РУКОЙ — иначе перечень отвечал бы про себя
# (класс, на котором учёт уже горел трижды: маска стендов, канарейка обёртки, сводка).
# ЧЕГО НЕ ДЕЛАЕТ: страховки (*.bak-*, *SNYATO*) не берёт — их смысл в том, чтобы лежать
# неизменными, и они множатся при каждой правке; подкаталоги не обходит (сейчас их нет,
# появятся — не увидит, и это надо будет назвать отдельно).
# ПОЧЕМУ ПОИМЁННО, А НЕ ОДНОЙ СУММОЙ, КАК ПАКЕТЫ: одна сумма на живой каталог краснела бы
# при каждой правке DOLGI.md без имени файла — вечное красное перестают читать вместе
# с настоящими находками.
PROCEDURY="${PROCEDURY_Q:-/opt/iskra/workspace/procedury}"   # подставной — только для проб (B-N-1217), как PARY_DORABOTKI
if [ ! -d "$PROCEDURY" ]; then
    echo "🔴 СЛЕПОТА РАЗРЯДА Q: каталога процедур нет по пути $PROCEDURY"
    echo "   Это про инструмент, не про документы: ниже их не будет вовсе."
else
    # 🔴 B-N-1217 (30.09.2026, условия Вениамина, мандат Забавы): КЛАСС ПИШЕТ-ПОДЪЁМ.
    # podyom-uzla ДОПИСЫВАЕТ журнал: перед строкой «ДО» публикует канон,
    # перед «ПОСЛЕ» — снимок; строки несут md5 опубликованных артефактов (B-N-1218).
    # Без класса ЛЮБОЙ подъём красил --check, и ночной registry-watchdog (07:30Z) слал владельцу
    # «беду», неотличимую от затёртого файла (29.09: половина строк расхождений — следы подъёмов).
    # ПРАВИЛО (только --check; --save узаконивает как прежде, list не трогается):
    #   журнал законен, если эталонная сумма = md5 его ПРЕФИКСА по строкам (только дописан);
    #   канон службы S законен, если в дописанной части журнала есть строка «| ДО | S |»,
    #   снимок S — если есть «| ПОСЛЕ| S |». Законная правка идёт в сверку ЭТАЛОННОЙ суммой
    #   (не расхождение) и называется поимённо строкой «ПИШЕТ-ПОДЪЁМ». Пропажа, новый файл,
    #   правка без строки подъёма этой службы, журнал не префиксом — расхождение, как прежде.
    # B-N-1218: файлы сверяются с md5 в ПОСЛЕДНЕЙ строке своей службы/фазы даже после --save.
    # Старые строки без md5 не дают льготу: остаётся сверка с манифестом.
    # ГРАНИЦА: согласованную подделку файла И его md5 в журнале это не аутентифицирует.
    # A-N-1724 (07.10, Михалыч/Искра): журнал подъёмов переехал из procedury в /var/log/podyom-uzla (root 644), прежний
    #   заморожен (root 444) и остаётся в procedury обычным файлом Q. Канон и снимок остаются в procedury, а строки ДО/ПОСЛЕ
    #   читаются из НОВОГО журнала. Его эталон — своя строка Q с его путём (ниже, после обхода procedury): без неё префикс
    #   дозаписи не установить, и любой подъём давал бы ложное расхождение канона. PP_ZHURNAL меняет путь (стенд).
    pp_k=""; pp_dopis=""; pp_zakonno=0; pp_imena=""; pp_z="${PP_ZHURNAL:-/var/log/podyom-uzla/zhurnal-podyomov.txt}"
    if [ "$MODE" = "--check" ] && [ -f "$pp_z" ]; then
        pp_star=$(awk -F'|' -v p="$pp_z" '$1=="Q" && $2==p {print $3}' "$MANIFEST" 2>/dev/null)
        if [ -n "$pp_star" ] && [ "$pp_star" != "НЕТ-ФАЙЛА" ]; then
            pp_n=$(wc -l < "$pp_z"); i=$pp_n
            # с конца: дописанных строк обычно единицы; не нашли префикс — pp_k пуст
            while [ "$i" -gt 0 ]; do
                [ "$(head -n "$i" "$pp_z" | md5sum | cut -d' ' -f1)" = "$pp_star" ] && { pp_k=$i; break; }
                i=$((i-1))
            done
            if [ -n "$pp_k" ]; then pp_dopis=$(tail -n +"$((pp_k+1))" "$pp_z")
            else echo "🔴 ПИШЕТ-ПОДЪЁМ: журнал подъёмов НЕ дописан, а переписан (эталон не префикс) — законность подъёмов не установить, следы подъёмов идут расхождением"
            fi
        fi
    fi
    PP_SLED_PRIBOR="${PP_SLED_PRIBOR:-/usr/local/libexec/podyom-uzla/check-sled.py}"
    pp_md5_checked=0; pp_legacy=0; pp_bed=0; pp_artifacts=0; pp_mismatch=0; pp_blind=0
    # A-N-1726 (07.10, Михалыч/Искра): канон и снимок переехали в каталог следа (dirname pp_z, root:root 755, файлы 0644).
    #   Сверка со следом (check-sled) и узаконивание по ДО/ПОСЛЕ — только для файлов ТАМ. Прежние копии в procedury застыли
    #   (их больше никто не пишет) и идут обычными строками Q: сверять их с журналом нельзя — первый же подъём сделал бы их
    #   ложно красными. Пустой glob (до засева) — пропуск по [ -f ].
    pp_dir="${pp_z%/*}"
    for f in "$PROCEDURY"/* "$pp_dir"/kanon-podyoma-*.txt "$pp_dir"/snimok-kanonov-*.txt; do
        [ -f "$f" ] || continue
        case "$f" in *.bak-*|*SNYATO*) continue ;; esac
        seen=$((seen+1))
        qs=$(md5sum "$f" 2>/dev/null | cut -d' ' -f1)
        [ -z "$qs" ] && { qs="НЕТ-ФАЙЛА"; missing=$((missing+1)); }
        pp_md5_ok=0; pp_phase=""; pp_service=""
        [ "${f%/*}" = "$pp_dir" ] && case "${f##*/}" in
            kanon-podyoma-*.txt) pp_phase="ДО"; pp_service="${f##*/kanon-podyoma-}" ;;
            snimok-kanonov-*.txt) pp_phase="ПОСЛЕ"; pp_service="${f##*/snimok-kanonov-}" ;;
        esac
        if [ "$MODE" = "--check" ] && [ -n "$pp_phase" ]; then
            pp_artifacts=$((pp_artifacts+1)); pp_service="${pp_service%.txt}.service"
            if pp_verify=$(/usr/bin/python3 -I -S -B "$PP_SLED_PRIBOR" --file "$f" --journal "$pp_z" --service "$pp_service" --phase "$pp_phase" --manifest "$MANIFEST" 2>&1); then
                case "$pp_verify" in
                    journal\ *) pp_md5_checked=$((pp_md5_checked+1)); pp_md5_ok=1 ;;
                    legacy\ *) pp_legacy=$((pp_legacy+1)) ;;
                    *) pp_bed=$((pp_bed+1)); pp_blind=$((pp_blind+1)); echo "🔴 ПИШЕТ-ПОДЪЁМ: $f: неизвестный ответ прибора" ;;
                esac
            else
                pp_rc=$?; pp_bed=$((pp_bed+1))
                if [ "$pp_rc" = 1 ]; then pp_mismatch=$((pp_mismatch+1)); else pp_blind=$((pp_blind+1)); fi
                echo "🔴 ПИШЕТ-ПОДЪЁМ: $pp_verify"
            fi
        fi
        if [ -n "$pp_k" ] && [ "$qs" != "НЕТ-ФАЙЛА" ]; then
            pp_ef=$(awk -F'|' -v p="$f" '$1=="Q" && $2==p {print $3}' "$MANIFEST" 2>/dev/null)
            if [ -n "$pp_ef" ] && [ "$pp_ef" != "$qs" ]; then
                pp_vid=""; pp_sl=""
                case "${f##*/}" in
                    zhurnal-podyomov.txt) pp_vid="ZH" ;;
                    kanon-podyoma-*.txt)  pp_vid="ДО";    pp_sl="${f##*/kanon-podyoma-}";  pp_sl="${pp_sl%.txt}.service" ;;
                    snimok-kanonov-*.txt) pp_vid="ПОСЛЕ"; pp_sl="${f##*/snimok-kanonov-}"; pp_sl="${pp_sl%.txt}.service" ;;
                esac
                pp_ok=0
                if [ "$pp_vid" = "ZH" ]; then pp_ok=1
                elif [ -n "$pp_vid" ] && [ "$pp_md5_ok" = 1 ] && printf '%s\n' "$pp_dopis" | awk -F'|' -v v="$pp_vid" -v s="$pp_sl" \
                        '{a=$2; b=$3; gsub(/^ +| +$/,"",a); gsub(/^ +| +$/,"",b); if (a==v && b==s) f=1} END{exit !f}'; then pp_ok=1
                fi
                [ "$pp_ok" = 1 ] && { qs="$pp_ef"; pp_zakonno=$((pp_zakonno+1)); pp_imena="$pp_imena ${f##*/}"; }
            fi
        fi
        printf 'Q|%s|%s\n' "$f" "$qs" >> "$tmp"
        [ "$MODE" = "list" ] && printf 'Q  %-62s %s\n     документ процедур\n' "$f" "$qs"
    done
    # A-N-1724: журнал подъёмов вне procedury — своя строка Q; законная дозапись (эталон — префикс) узаконивается, как
    #   прежде у zhurnal-podyomov.txt в procedury. Нет файла — НЕТ-ФАЙЛА, как у прочих Q.
    case "$pp_z" in
        "$PROCEDURY"/*) ;;
        *)  seen=$((seen+1))
            qs=$(md5sum "$pp_z" 2>/dev/null | cut -d' ' -f1)
            [ -z "$qs" ] && { qs="НЕТ-ФАЙЛА"; missing=$((missing+1)); }
            if [ -n "$pp_k" ] && [ "$qs" != "НЕТ-ФАЙЛА" ]; then
                pp_ef=$(awk -F'|' -v p="$pp_z" '$1=="Q" && $2==p {print $3}' "$MANIFEST" 2>/dev/null)
                [ -n "$pp_ef" ] && [ "$pp_ef" != "$qs" ] && { qs="$pp_ef"; pp_zakonno=$((pp_zakonno+1)); pp_imena="$pp_imena ${pp_z##*/}"; }
            fi
            printf 'Q|%s|%s\n' "$pp_z" "$qs" >> "$tmp"
            [ "$MODE" = "list" ] && printf 'Q  %-62s %s\n     журнал подъёмов (A-N-1724)\n' "$pp_z" "$qs" ;;
    esac
    [ "$MODE" = "--check" ] && echo "ПИШЕТ-ПОДЪЁМ: артефактов=$pp_artifacts md5 подтверждено=$pp_md5_checked legacy-по-манифесту=$pp_legacy md5-расхождений=$pp_mismatch слепот=$pp_blind ошибок=$pp_bed"
    [ "$pp_zakonno" -gt 0 ] && echo "ПИШЕТ-ПОДЪЁМ: законно изменено $pp_zakonno (журнал подъёмов дописан $(printf '%s\n' "$pp_dopis" | grep -c .) строк):$pp_imena — не расхождение; --save узаконит (B-N-1217)"
fi

# РАЗРЯД L: БОЕВЫЕ ФАЙЛЫ /usr/local/libexec. Заведён 23.09.2026, A-N-709.
# 🔴 ЗАЧЕМ. После перевода A-N-676 в libexec легли root-файлы (svodka/*, podyom-uzla/*),
# а раньше — pamyat-seam/* (A-N-018/087/091). Эталон не вёл ни одного пути libexec: их
# стерегла только сверка пар «исходник = бой», а она слепа к правке, внесённой одинаково
# в обе половины, и к файлу без тёзки в dorabotki (так лежит весь pamyat-seam).
# СОСТАВ БЕРЁТСЯ ОБХОДОМ, НЕ СПИСКОМ РУКОЙ, как в разряде Q: новый файл, пропажа и правка
# видны поимённо. Обход РЕКУРСИВНЫЙ — в libexec подкаталоги по инструментам.
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: страховки (*.bak*) не берёт; ссылки и каталоги не сверяет.
# СЛЕПОТА: каталога нет или sudo -n не отдал список — строка «СЛЕПОТА РАЗРЯДА L»,
# и ниже нет ни одной позиции L; это про прибор, не про файлы.
# ЧЕГО НЕ ЛОВИТ: владельца и режим (сумма — только содержимое).
# (список spisok_L и суммы сняты выше, вместе с целями — B-N-961)
if [ -z "$spisok_L" ]; then
    echo "🔴 СЛЕПОТА РАЗРЯДА L: файлов под $LIBEXEC не получено (нет каталога или отказ sudo -n)"
    echo "   Это про инструмент, не про файлы: ниже их не будет вовсе."
else
    while IFS= read -r f; do
        seen=$((seen+1))
        ls_=${SUMMA_MD5["$f"]:-}
        [ -z "$ls_" ] && { ls_="НЕТ-ФАЙЛА"; missing=$((missing+1)); }
        printf 'L|%s|%s\n' "$f" "$ls_" >> "$tmp"
        [ "$MODE" = "list" ] && printf 'L  %-62s %s\n     боевой файл libexec\n' "$f" "$ls_"
    done <<< "$spisok_L"
fi

# РАЗРЯД Y: DROP-IN ЮНИТОВ systemd — $DROPIN_KAT/<юнит>.d/*.conf. Заведён 29.09.2026 (Искра, находка к B-N-1175, слово Забавы).
# 🔴 ЗАЧЕМ. Drop-in меняет живую службу (группы, окружение, пределы, ExecStartPost), а учёт вёл их только поимённо E-строкой —
# 40 из 77 на 29.09; 37 не видел вовсе, в том числе свежий codex-compaction-vyborka.conf: правка или пропажа шли МОЛЧА.
# СОСТАВ БЕРЁТСЯ ОБХОДОМ, как в L: новый drop-in, пропажа и правка видны поимённо. Кто уже под E-строкой — там и остаётся
# (не дублируется). ЧУЖИЕ — перечнем CHUZHIE_Y с причиной (не узакониваются; их правку разряд НЕ видит — это его граница).
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: не *.conf (страховки .bak-*, .disabled-*) — systemd их не читает; ссылки (-type f).
# СЛЕПОТА: обход не дал ни одного файла (нет каталога / отказ sudo -n) — строка «СЛЕПОТА РАЗРЯДА Y».
# ЧЕГО НЕ ЛОВИТ: drop-in в /run/systemd/system и /usr/lib/systemd/system; drop-in-ссылки; глубже одного уровня; владельца и режим;
# что drop-in ПРИМЕНЁН живой службой (сумма — файла на диске; живое — systemctl show, это другой вопрос).
if [ -z "$spisok_Y_vse" ]; then
    echo "🔴 СЛЕПОТА РАЗРЯДА Y: drop-in под $DROPIN_KAT не получено (нет каталога или отказ sudo -n)"
    echo "   Это про инструмент, не про файлы: ниже их не будет вовсе."
else
    [ -n "$spisok_Y" ] && while IFS= read -r f; do
        seen=$((seen+1))
        ys=${SUMMA_MD5["$f"]:-}
        [ -z "$ys" ] && { ys="НЕТ-ФАЙЛА"; missing=$((missing+1)); }
        printf 'Y|%s|%s\n' "$f" "$ys" >> "$tmp"
        [ "$MODE" = "list" ] && printf 'Y  %-62s %s\n     drop-in юнита\n' "$f" "$ys"
    done <<< "$spisok_Y"
    echo "разряд Y (drop-in $DROPIN_KAT): обойдено $(grep -c . <<< "$spisok_Y_vse"), под E-строками $y_pod_E, чужих по перечню $y_chuzhih (не узакониваются), в разряде $(grep -c . <<< "$spisok_Y")"
fi

# Счётчик разошедшихся пар (ниже — пары «исходник ↔ боевой root-файл», A-N-676).
para_bed=0

# ПАРЫ «ИСХОДНИК ↔ БОЕВОЙ root-ФАЙЛ» (A-N-676): перечень — данные в pary-boj.txt, а не код.
# Расхождение, нет исходника, нет боевого, нечитаемый перечень, root-файл с тёзкой в dorabotki вне
# перечня — всё это para_bed, то есть код 1. Суммы боя берутся через sudo -n (libexec может быть закрыт).
# ЧЕГО НЕ ЛОВИТ: перенос под ДРУГИМ именем без тёзки в dorabotki (кроме *.sh и libexec/<путь>) —
# такую пару надо вписать рукой; и «сверено» не значит «верно»: равные исходник и бой могут быть оба плохи.
PARY="${PARY_BOJ:-/opt/iskra/workspace/dorabotki/pary-boj.txt}"
PARY_DOR="${PARY_DORABOTKI:-/opt/iskra/workspace/dorabotki}"      # где искать тёзок (для проб — подставной)
PARY_KORNI="${PARY_BOJ_KORNI:-/usr/local/bin /usr/local/sbin /usr/local/libexec}"   # где лежит бой (sbin с 25.09, B-N-649)
PARY_VLAD="${PARY_VLADELEC:-root}"                                  # чьи файлы боя считаются перенесёнными
pary_vsego=0; pary_soshlos=0
if [ ! -r "$PARY" ]; then
    echo "ПАРЫ исходник↔бой: СЛЕПОТА — перечня нет или не читается: $PARY" >&2; para_bed=$((para_bed+1))
else
    obyavleno=""
    # B-N-961: суммы боя всех пар — одним sudo -n (было по вызову на пару).
    boi=(); while IFS='|' read -r ish boj; do case "$ish" in ''|'#'*) continue ;; esac; boi+=("$boj"); done < "$PARY"
    declare -A SUMMA_SHA=()
    if [ "${#boi[@]}" -gt 0 ]; then
        while IFS= read -r -d '' rec; do SUMMA_SHA["${rec:66}"]=${rec:0:16}; done < <(sudo -n sha256sum -z -- "${boi[@]}" 2>/dev/null)
    fi
    while IFS='|' read -r ish boj; do
        case "$ish" in ''|'#'*) continue ;; esac
        pary_vsego=$((pary_vsego+1)); obyavleno="$obyavleno $boj "
        si=$(sha256sum "$ish" 2>/dev/null | cut -c1-16)
        sb=${SUMMA_SHA["$boj"]:-}
        if [ -z "$si" ]; then echo "ПАРА $boj: исходника нет — $ish" >&2; para_bed=$((para_bed+1))
        elif [ -z "$sb" ]; then echo "ПАРА $boj: боевого файла нет (или не читается) — исходник $si" >&2; para_bed=$((para_bed+1))
        elif [ "$si" != "$sb" ]; then
            echo "ПАРА $boj: РАСХОЖДЕНИЕ — бой $sb ($(sudo -n stat -c %y "$boj" 2>/dev/null | cut -c1-16)), исходник $si ($(stat -c %y "$ish" | cut -c1-16)) $ish" >&2
            para_bed=$((para_bed+1))
        else pary_soshlos=$((pary_soshlos+1)); fi
    done < "$PARY"
    [ "$pary_vsego" -gt 0 ] || { echo "ПАРЫ исходник↔бой: СЛЕПОТА — в перечне 0 пар" >&2; para_bed=$((para_bed+1)); }
    # полнота: root-файл в /usr/local/{bin,sbin,libexec} с тёзкой в dorabotki обязан быть объявлен
    # (sbin добавлен 25.09, B-N-649: zastryalo-v-shcheli разошёлся с исходником молча — корня не было в обходе)
    while read -r boj; do
        imya=${boj##*/}; ot=${boj#*/libexec/}
        for c in "$PARY_DOR/$imya" "$PARY_DOR/$imya.sh" "$PARY_DOR/libexec/$ot"; do
            if [ -f "$c" ]; then
                case "$obyavleno" in *" $boj "*) ;; *) echo "ПАРА $boj: НЕ ОБЪЯВЛЕНА — есть тёзка $c, строки в $PARY нет" >&2; para_bed=$((para_bed+1)) ;; esac
                break
            fi
        done
    done < <(sudo -n find $PARY_KORNI -type f -user "$PARY_VLAD" ! -name '*.bak*' 2>/dev/null)
    echo "пары исходник↔бой: сошлось $pary_soshlos из $pary_vsego (перечень $PARY)"
fi

# ПРИЗНАК СОБСТВЕННОЙ ИСПРАВНОСТИ: список не может быть пуст
if [ "$seen" -lt 10 ]; then
    echo "СЛЕПОТА: разобрано $seen строк списка, ожидалось не менее 10" >&2
    exit 1
fi

# КЛАСС C: обход app всех агентов из реестра (B-N-1798).
# Для каждого дерева своя граница: mtime package-lock.json + 60 секунд.
# package.json самого app — прежнее исключение; файлы пакетов внутри не исключаются.
# NASHI_C_REESTR — путь реестра для изолированных проб; по умолчанию боевой.
C_REESTR="${NASHI_C_REESTR:-/etc/agent-registry/agents.yaml}"
C_APPS="$VREM_KAT/c-apps"
if ! python3 - "$C_REESTR" > "$C_APPS" <<'PY_C_APPS'
import pathlib, re, sys, yaml
try:
    document = yaml.safe_load(pathlib.Path(sys.argv[1]).read_text())
    agents = document['agenty']
    if not isinstance(agents, list) or not agents:
        raise ValueError()
    rows = []
    names, homes = set(), set()
    for agent in agents:
        name = agent['imya']
        home = agent['namerenie']['dom']
        if (not isinstance(name, str) or not re.fullmatch(r'[a-z][a-z0-9_-]{0,39}', name)
                or not isinstance(home, str) or not home.startswith('/')
                or any(c in home for c in '\n\r\t\0') or '..' in pathlib.PurePosixPath(home).parts):
            raise ValueError()
        home = str(pathlib.PurePosixPath(home))
        if name in names or home in homes:
            raise ValueError()
        names.add(name); homes.add(home)
        rows.append((name, home + '/app'))
    for name, app in sorted(rows):
        print(name + '\t' + app)
except (OSError, ValueError, KeyError, TypeError, yaml.YAMLError):
    print('СЛЕПОТА: реестр области класса C не прочитан или негоден: ' + sys.argv[1], file=sys.stderr)
    sys.exit(1)
PY_C_APPS
then
    exit 1
fi
C_ERR="$VREM_KAT/c-err"
C_HITS="$VREM_KAT/c-hits"
C_TOTAL="$VREM_KAT/c-total"
c_hits=0; c_total=0; c_apps=0
while IFS=$'\t' read -r C_AGENT APP; do
    LOCK="$APP/package-lock.json"
    if ! sudo -n test -d "$APP" || ! sudo -n test -r "$LOCK"; then
        echo "СЛЕПОТА: класс C [$C_AGENT] — нет дерева $APP или не читается $LOCK" >&2
        exit 1
    fi
    if ! C_MTIME=$(sudo -n stat -c %Y "$LOCK") || [[ ! "$C_MTIME" =~ ^[0-9]+$ ]]; then
        echo "СЛЕПОТА: класс C [$C_AGENT] — не снять mtime $LOCK" >&2; exit 1
    fi
    if ! BOUND=$(date -d "@$((C_MTIME + 60))" '+%Y-%m-%d %H:%M:%S'); then
        echo "СЛЕПОТА: класс C [$C_AGENT] — не вычислить границу $LOCK" >&2; exit 1
    fi
    # Код и stderr проверяются отдельно: ноль после отказа не станет чистотой.
    if ! sudo -n find "$APP" -type f -printf '.\n' > "$C_TOTAL" 2> "$C_ERR" || [ -s "$C_ERR" ]; then
        echo "СЛЕПОТА: пересчёт класса C [$C_AGENT] не состоялся: $APP" >&2
        sed 's/^/    /' "$C_ERR" >&2; exit 1
    fi
    C_FILES=$(wc -l < "$C_TOTAL")
    if [ "$C_FILES" -eq 0 ]; then
        echo "СЛЕПОТА: класс C [$C_AGENT] — find не увидел файлов в $APP" >&2; exit 1
    fi
    if ! sudo -n find "$APP" -newermt "$BOUND" -type f ! -path "$APP/package.json" -print0 > "$C_HITS" 2> "$C_ERR" || [ -s "$C_ERR" ]; then
        echo "СЛЕПОТА: обход класса C [$C_AGENT] не состоялся: $APP, граница $BOUND" >&2
        sed 's/^/    /' "$C_ERR" >&2; exit 1
    fi
    C_COUNT=$(tr -cd '\000' < "$C_HITS" | wc -c)
    echo "класс C [$C_AGENT]: $C_COUNT [app: $APP, видно файлов: $C_FILES, граница: $BOUND]"
    while IFS= read -r -d '' C_PATH; do printf '    класс C [%s]: %q\n' "$C_AGENT" "$C_PATH"; done < "$C_HITS"
    c_hits=$((c_hits + C_COUNT)); c_total=$((c_total + C_FILES)); c_apps=$((c_apps + 1))
done < "$C_APPS"
if [ "$c_apps" -eq 0 ]; then
    echo "СЛЕПОТА: область класса C пуста — ни одно app не проверено" >&2; exit 1
fi
rm -f "$C_ERR" "$C_HITS" "$C_TOTAL" "$C_APPS"

if [ "$MODE" = "list" ] || [ "$MODE" = "--save" ]; then
    echo
    echo "класс C (правки в деревьях приложения): $c_hits  [видно файлов: $c_total, деревьев: $c_apps; границы каждого — выше]"
    echo "строк списка: $seen, отсутствует: $missing, пара бой/заготовка разошлась: $para_bed"
    dubli_v_spiske

    if [ "$MODE" = "--save" ]; then
        # 🔴 ПАКЕТНЫЙ --save УЗАКОНИВАЛ ПОРЧУ МОЛЧА (воспроизведено 24.08.2026).
        # Опыт: испортить стенд -> --check краснеет (код 1) -> вызвать --save ->
        # --check зелёный, ОБА учёта зелёные, порча в эталоне. Это не модель
        # злоумышленника: --save наш ежедневный инструмент, и достаточно одной
        # невнимательности. Дисциплина «снять манифест ДО и сверить diff» держалась
        # на руке; рука забывает. Теперь узаконивание невозможно молча.
        # ПОЧЕМУ ЧИСЛОМ, А НЕ ПРОСТЫМ «да»: подтверждение вслепую механически
        # дописывается к команде и перестаёт быть подтверждением. Число можно
        # узнать только сухим прогоном, то есть посмотрев, ЧТО именно узаконивается.
        # ГДЕ НЕ ДЕЙСТВУЕТ: против намеренной согласованной правки файла и эталона
        # (у кого есть право писать оба — тот и так может); против невнимательности
        # действует. И не проверяет, ВЕРНО ли новое состояние — это `verify`.
        sort "$tmp" > "$tmp.new"
        # 🔴 УЗАКОНИВАНИЕ ПО ОБЛАСТИ (--tolko <образец пути>), заведено 06.09.2026 после
        # случая на себе: я подставила число подтверждения КОМАНДОЙ вместо чтения перечня
        # и узаконила 18 строк вместо одной — вместе с моей правкой проехал ЧУЖОЙ монтаж
        # пакета связи, и первый учёт стал зелёным на непринятой редакции.
        # Защита числом требует ВНИМАНИЯ, а внимание автоматизируется за одну команду —
        # значит это не защита. Область же не автоматизируется: её надо НАЗВАТЬ, и назвать
        # можно только то, о чём знаешь.
        # ГДЕ НЕ ДЕЙСТВУЕТ: если чужая правка попала в ТУ ЖЕ область, что и своя, она
        # проедет так же. Это сужение окна, а не запирание двери.
        if [ -n "${TOLKO:-}" ]; then
            # Итог = старый эталон ВНЕ области + новое состояние ВНУТРИ области.
            awk -F'|' -v obr="$TOLKO" 'index($2, obr) == 0' "$MANIFEST" > "$tmp.vne" 2>/dev/null || : > "$tmp.vne"
            awk -F'|' -v obr="$TOLKO" 'index($2, obr) > 0'  "$tmp.new"  > "$tmp.vnutri"
            cat "$tmp.vne" "$tmp.vnutri" | sort > "$tmp.new2"
            mv "$tmp.new2" "$tmp.new"
        fi
        if [ ! -r "$MANIFEST" ]; then
            cp "$tmp.new" "$MANIFEST"
            echo "эталона не было — СОЗДАН: $MANIFEST (позиций: $seen)"
            rm -f "$tmp.new"
            exit 0
        fi
        diff -u "$MANIFEST" "$tmp.new" > "$tmp.sdiff" || true
        izm=$(grep -cE '^[-+][^-+]' "$tmp.sdiff" || true)
        if [ "$izm" -eq 0 ]; then
            # 🔴 ПРИ --tolko «ноль изменений» ЗНАЧИТ ДРУГОЕ, И СЛИВАТЬ ИХ НЕЛЬЗЯ.
            # Без области ноль = «эталон совпадает с машиной». С областью ноль = «в ЭТОЙ
            # области нечего узаконивать», а вне её расхождения могут быть — и сообщение
            # «совпадает с машиной» было бы прямой ложью. Поймано порчей в тот же заход:
            # образец, под который не подходит ничего, при живом расхождении печатал
            # «совпадает».
            if [ -n "${TOLKO:-}" ]; then
                sort "$tmp" > "$tmp.vsyo"
                vsego_izm=$(diff -u "$MANIFEST" "$tmp.vsyo" 2>/dev/null | grep -cE '^[-+][^-+]' || true)
                rm -f "$tmp.vsyo"
                echo "в области «$TOLKO» узаконивать нечего (изменений 0)."
                echo "ВНЕ ОБЛАСТИ расхождений: ${vsego_izm:-0} — это НЕ «эталон совпадает с машиной»."
            else
                echo "эталон уже совпадает с машиной — писать нечего (изменений 0)"
            fi
            rm -f "$tmp.new" "$tmp.sdiff"
            exit 0
        fi
        echo "УЗАКОНИВАЕТСЯ (строк: $izm)${TOLKO:+ — ТОЛЬКО в области «$TOLKO»}:"
        grep -E '^[-+][^-+]' "$tmp.sdiff"
        # 🔴 B-N-1032 (26.09.2026, находка Искры при B-N-1028, Вениамин): --save УЗАКОНИВАЛ ОТСУТСТВИЕ МОЛЧА.
        # Строка списка, чьего файла нет на диске, ложилась в эталон с суммой «НЕТ-ФАЙЛА» — и --check потом
        # давал 0 при несуществующем файле (стенд не смонтирован, а учёт зелёный). Теперь новая «+»-строка с
        # «НЕТ-ФАЙЛА» — ОТКАЗ записи (код 3) с перечнем путей; узаконить отсутствие можно только ЯВНО и С
        # ПРИЧИНОЙ: NASHI_NET_FAJLA_PRICHINA="<почему файла законно нет>" — тогда пишется и строка в журнал
        # (logger -t nashi-dorabotki). Пустая или из пробелов причина — не причина.
        # ⚠️ ЧЕГО НЕ ЛОВИТ: «НЕТ-ФАЙЛА», уже лежащие в эталоне (их diff не показывает — они не узакониваются
        #    заново); файл, пропавший ПОСЛЕ --save (это ловит --check: сумма разошлась); и пустой файл — у него
        #    есть сумма, это не «нет файла».
        # B-N-1744 (07.10, Вениамин, low): строка LINKS без ссылки («-> НЕТ-ССЫЛКИ») — то же отсутствие, тот же отказ.
        #    Не ловит «ПРАВИТ-АГЕНТ:СЛЕПОТА». Отказ канона P отсекается раньше (B-N-2048, 14.10).
        net_fajla=$(grep -E '^\+[A-Z]\|[^|]*\|(НЕТ-ФАЙЛА|-> НЕТ-ССЫЛКИ)$' "$tmp.sdiff" | cut -d'|' -f2 || true)
        if [ -n "$net_fajla" ]; then
            nf_chislo=$(printf '%s\n' "$net_fajla" | grep -c . || true)
            echo "⚠️ УЗАКОНИВАЕТСЯ ОТСУТСТВИЕ — файла нет на диске ($nf_chislo):"
            printf '%s\n' "$net_fajla" | sed 's/^/     /'
            if [ "$ARG2" = "--izmenenij" ] && [ -z "$(printf '%s' "${NASHI_NET_FAJLA_PRICHINA:-}" | tr -d '[:space:]')" ]; then
                echo >&2
                echo "ЭТАЛОН НЕ ПЕРЕПИСАН: узаконить отсутствие файла можно только явно, с причиной:" >&2
                echo "  NASHI_NET_FAJLA_PRICHINA=\"<почему файла законно нет>\" $0 --save --izmenenij $izm${TOLKO:+ --tolko $TOLKO}" >&2
                echo "Обычный порядок — сначала файл на диск (монтаж), потом --save." >&2
                rm -f "$tmp.new" "$tmp.sdiff"
                exit 3
            fi
        fi
        if [ -n "${TOLKO:-}" ]; then
            # 🔴 ЧТО ОСТАЁТСЯ ВНЕ ОБЛАСТИ — НАЗЫВАЕТСЯ ЧИСЛОМ. Молчание тут читалось бы как
            # «больше расхождений нет», а означает «мы туда не смотрели».
            sort "$tmp" > "$tmp.vsyo"
            diff -u "$MANIFEST" "$tmp.vsyo" 2>/dev/null | grep -cE '^[-+][^-+]' > "$tmp.vsego_izm" || true
            vsego_izm=$(cat "$tmp.vsego_izm" 2>/dev/null || echo 0)
            vne=$(( vsego_izm - izm ))
            [ "$vne" -lt 0 ] && vne=0
            echo "ВНЕ ОБЛАСТИ остаётся расхождений: $vne (учёт по ним будет краснеть — это не сбой)"
            rm -f "$tmp.vsyo" "$tmp.vsego_izm"
        fi
        if [ "$ARG2" != "--izmenenij" ]; then
            echo >&2
            echo "ЭТАЛОН НЕ ПЕРЕПИСАН: изменения показаны, но не подтверждены." >&2
            echo "Прочтите список выше и повторите: --save --izmenenij $izm" >&2
            rm -f "$tmp.new" "$tmp.sdiff"
            exit 3
        fi
        if [ "$ARG3" != "$izm" ]; then
            echo >&2
            echo "ЭТАЛОН НЕ ПЕРЕПИСАН: подтверждено $ARG3 строк, а меняется $izm." >&2
            echo "Расхождение числа значит, что список изменился с прошлого прогона." >&2
            rm -f "$tmp.new" "$tmp.sdiff"
            exit 3
        fi
        cp "$tmp.new" "$MANIFEST"
        echo "эталон ПЕРЕЗАПИСАН: $MANIFEST (узаконено строк: $izm)"
        if [ -n "$net_fajla" ]; then
            logger -t nashi-dorabotki "B-N-1032: узаконено ОТСУТСТВИЕ ($nf_chislo): $(printf '%s' "$net_fajla" | tr '\n' ' ')· причина: ${NASHI_NET_FAJLA_PRICHINA:-}" 2>/dev/null \
                && echo "строка в журнал (logger -t nashi-dorabotki) записана: отсутствие $nf_chislo, причина названа" \
                || echo "⚠️ строка в журнал НЕ записалась (logger) — причину впишите в сообщение коммита эталона"
        fi
        rm -f "$tmp.new" "$tmp.sdiff"
    else
        echo "эталон не тронут (перезаписать: --save)"
    fi
    exit 0
fi

# --- РАЗРЯД: ФАЙЛ В КАТАЛОГЕ, КОТОРОГО НЕТ В СПИСКЕ (долг 16) -----------------
# 🔴 Учёт по построению слеп ко всему, чего в списке нет: новый инструмент в него
# сам не попадает, и зелёное означает «не вижу», а не «цело». Так прожили вне обеих
# опор манифесты профилей и три инструмента. Признак ищет, ИСКЛЮЧЕНИЯ судят: молча
# пропускать нельзя, но и краснеть на снятом и на мусоре — значит приучить себя
# к красному.
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: разряд смотрит ТОЛЬКО каталог dorabotki (мою мастерскую) и
# только верхний уровень; про чужие каталоги он ничего не знает и знать не должен.
# 🔴 ОН ПЕЧАТАЕТ, НО НЕ СУДИТ — код возврата не меняет. Черновик имеет право полежать
# час; краснеть на каждом новом файле значит приучить себя к красному, а приучённый
# к красному перестаёт его читать. Видимость обязательна, приговор — нет.
# --- ЗАМОРОЗКА ПРЕДМЕТОВ: СВЕРКА ПРИ КАЖДОМ СВЕДЕНИИ УЧЁТА -------------------
# 🔴 ЗАЧЕМ ЗДЕСЬ. Признак `zamorozka-predmeta` до 03.09.2026 звался ТОЛЬКО МОЕЙ РУКОЙ:
# точек запуска было ноль (ни таймера, ни юнита, ни вызова из чужого скрипта —
# проверено). Значит заморозка держалась на дисциплине, только с опорой на скрипт,
# а не на памяти. Вопрос аудитора был точным: кто зовёт, когда, что делает при
# расхождении.
# Теперь сверка идёт при КАЖДОМ `--check`, то есть при каждом сведении учёта —
# а его я делаю после любой правки, это часть лестницы.
# 🔴 ПЕЧАТАЕТ, НО НЕ СУДИТ: код учёта не меняется. Иначе пять чужих тарболов в
# годном ящике (предметы Михалыча) сделали бы мой учёт вечно красным — ровно то,
# от чего мы лечились всю ночь. Свой предмет виден строкой «совпало N».
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: остановить подачу отсюда нельзя — публикует не эта машина.
# Максимум, что здесь возможно, — чтобы расхождение НЕ ОСТАЛОСЬ НЕЗАМЕЧЕННЫМ.
# 🔴 РАЗРЯД «ПРИМЕНЕНИЯ ОБЁРТКИ» — заведён 03.09.2026 по предложению координатора.
# Существующий и неприменяемый механизм НЕОТЛИЧИМ от отсутствующего и ХУЖЕ него: он
# числится сделанным и в любом обзоре выглядит закрытым пунктом. Замер: за ночь 02→03.09
# `progon` существовал, был проверен на красном и зелёном — и не позвался НИ РАЗУ, пока
# код возврата затирался девять раз. Поэтому считаем не наличие, а ЧИСЛО ПРИМЕНЕНИЙ.
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: ноль применений НЕ означает, что класс не случался — прямой запуск
# команды обёртке не виден. Разряд печатает и не судит: код учёта он не меняет, потому
# что «сегодня не звала» бывает законно (день без прогонов).
# 🔴 РАЗРЯД: ОПИСАНИЕ ОБЕЩАЕТ КОНТРОЛЬ ЗРЯЧЕСТИ — КОД ОБЯЗАН ЕГО ДАВАТЬ (04.09.2026).
# ЗАЧЕМ. Наш живой класс — «строка обещает больше, чем даёт»: за одни сутки он стрелял
# трижды (счёт apt против показанного перечня; описание метапакета против состава;
# объявленные замены, чьи якоря протухли). Описание инструмента в этом списке — такой же
# текст: обещав «контроль зрячести встроен ключом --kontrol», оно читается как готовая
# возможность, и следующий позовёт ключ, которого нет.
# Отдельно про наш порядок ошибок: конфиг, объявленный РАНЬШЕ кода, — тихий ноль. Здесь
# то же самое, только в описании: обещание, записанное раньше кода, неотличимо от готового.
# ГДЕ НЕ ПРИМЕНЯЕТСЯ: разряд не проверяет, что контроль РАБОТАЕТ и что он зряч — только
# что обещанный ключ есть в коде. «Ключ есть» и «контроль ловит» — разные утверждения.
# И он ничего не говорит о тех, кто контроля не обещает: их большинство, это отдельный долг.
obeshchannyj_kontrol() {
    local obeshchano=0 net=0 stroka put opis
    while IFS= read -r stroka; do
        case "$stroka" in [A-E]\|*) : ;; *) continue ;; esac
        put=${stroka#*|}; opis=${put#*|}; put=${put%%|*}
        case "$opis" in *--kontrol*|*"онтроль зрячести встроен"*) : ;; *) continue ;; esac
        obeshchano=$((obeshchano+1))
        if [ ! -r "$put" ]; then
            echo "  🔴 обещан контроль, а файла нет: $put"; net=$((net+1)); continue
        fi
        if ! grep -q -- '--kontrol' "$put" 2>/dev/null; then
            echo "  🔴 описание обещает --kontrol, в коде его НЕТ: $put"; net=$((net+1))
        fi
    done < "$0"
    if [ "$obeshchano" -eq 0 ]; then
        echo "обещанный контроль зрячести: НИ ОДИН инструмент его не обещает — проверять нечего"
    elif [ "$net" -eq 0 ]; then
        echo "обещанный контроль зрячести: $obeshchano обещают, у всех ключ в коде есть" \
             "(что он ЛОВИТ — этим разрядом не проверяется)"
    else
        echo "  обещали $obeshchano, ключа нет у $net"
    fi
    [ "$net" -eq 0 ]
}

primeneniya_obyortki() {
    local f="${PROGON_UCHYOT:-/opt/iskra/workspace/.progon-primeneniya}" sutki n
    [ -r "$f" ] || { echo "применения progon: файла учёта нет — обёртка не звалась ни разу"; return 0; }
    sutki=$(date -u -d '1 day ago' +%Y-%m-%dT%H:%M:%SZ 2>/dev/null) || sutki=""
    if [ -n "$sutki" ]; then
        n=$(awk -v s="$sutki" '$0 >= s' "$f" | wc -l)
    else
        n=$(wc -l < "$f")
    fi
    if [ "$n" -eq 0 ]; then
        echo "🔴 применения progon за сутки: 0 — механизм есть и НЕ ПРИМЕНЯЕТСЯ."
        echo "   Это дисциплина, а не устройство: в обзоре пункт выглядит закрытым."
    else
        echo "применения progon за сутки: $n"
    fi
    # граница роста: держим только последние 7 суток, иначе файл растёт без предела.
    # 🔴 ПЕРЕЗАПИСЫВАЕМ СОДЕРЖИМОЕ, А НЕ ПОДМЕНЯЕМ ФАЙЛ (03.09.2026). Прежде здесь стоял
    # `mv "$f.tmp" "$f"`, и это меняло ВЛАДЕЛЬЦА: сторож реестров ходит по таймеру под
    # root и зовёт этот учёт, после чего файл доставался root — а мои обычные вызовы
    # переставали в него писать ВОВСЕ и молча. Счёт применений занижался, и занижение
    # читается как «механизм не применяют»: прибор, мерящий дисциплину, начинал на неё
    # клеветать. Замер до/после: iskra -> root за один прогон сторожа.
    # 📌 КЛАСС: уход за файлом, сделанный ЧУЖОЙ рукой, меняет его хозяина. Граница роста
    # у защиты была, границы «чьей рукой» — не было. `> "$f"` пишет в тот же inode,
    # владелец и права сохраняются.
    local nedelya
    nedelya=$(date -u -d '7 days ago' +%Y-%m-%dT%H:%M:%SZ 2>/dev/null) &&         awk -v s="$nedelya" '$0 >= s' "$f" > "$f.tmp" 2>/dev/null &&         cat "$f.tmp" > "$f" 2>/dev/null; rm -f "$f.tmp" 2>/dev/null
    return 0
}

zamorozka_pri_svedenii() {
    local z=/opt/iskra/workspace/dorabotki/zamorozka-predmeta out
    [ -x "$z" ] || { echo "⚠️  заморозка: нет $z — сверка предметов НЕ ПРОВОДИЛАСЬ"; return 0; }
    out=$(env HOME="$NASHI_HOME" "$z" 2>&1); k=$?
    # 🔴 Шаблон разбора чужого вывода — тоже предмет: 03.09.2026 я разбила строку ИТОГ
    # на две (назвала, что с чем сравнивается), и этот grep стал возвращать ПУСТО, а код
    # остался прежним. Сводка молча опустела. Берём обе строки: заголовок и числа.
    printf 'заморозка предметов: %s (код %s)\n' "$(printf '%s' "$out" | command grep -oE 'совпало [0-9]+, разошлось [0-9]+.*' | tail -1)" "$k"
    [ "$k" -eq 1 ] && printf '%s\n' "$out" | command grep -E 'ЗАМОРОЗКА НАРУШЕНА|FAIL .*= ' | head -3
    return 0
}

novye_vne_uchyota() {
    local kat=/opt/iskra/workspace/dorabotki rel ish boj n=0 pary_ish=" "
    # 🔴 ИСХОДНИК ОБЪЯВЛЕННОЙ ПАРЫ — ПОД УЧЁТОМ, ЕСЛИ ЕГО БОЙ В ЭТАЛОНЕ (B-N-649, 25.09.2026).
    # Раздел «ПАРЫ» держит его равным бою, а бой держит эталон. Прежде правило о парах не
    # знало и называло libexec/a2a-v2.py и libexec/podyom-uzla вне учёта при каждом прогоне.
    # Бой не в эталоне — исходник НЕ засчитывается: равенство неучтённому ничего не держит.
    if [ -r "$PARY" ]; then
        while IFS='|' read -r ish boj; do
            case "$ish" in ''|'#'*) continue ;; esac
            grep -qF "|$boj|" "$MANIFEST" && pary_ish="$pary_ish$ish "   # «|» с обеих сторон: не подстрока чужого пути (B-N-953)
        done < "$PARY"
    fi
    # 🔴 ПОДКАТАЛОГ РАЗБИРАЕТСЯ, А НЕ СЧИТАЕТСЯ ОДНИМ ЭЛЕМЕНТОМ (05.09.2026).
    # Прежде обход шёл только по верхнему уровню и сверял имя как «dorabotki/ИМЯ|».
    # Каталог stendy/ был в манифесте своим ФАЙЛОМ (dorabotki/stendy/stend-…|), а
    # разряд искал строку «dorabotki/stendy|» — и кричал вечно. Постоянное красное
    # перестают читать, и вместе с ним перестают читать настоящие находки разряда.
    # Вносить каталог в исключения было нельзя: тогда невидимым стало бы всё, что
    # внутри, — то есть разряд лечили бы созданием слепоты.
    # С 25.09 (B-N-649) обход идёт НА ВСЮ ГЛУБИНУ: прежде разбирался один уровень, и
    # каталог второго уровня (libexec/podyom-uzla) назывался одним элементом.
    # ГРАНИЦА: скрытые имена (.git, .ishody), __pycache__, *.bak-*, SNYATO не смотрятся вовсе,
    # вместе со всем, что внутри них.
    while IFS= read -r -d '' rel; do
        rel=${rel#"$kat"/}
        # Передачи — это ПИСЬМА, лежащие рядом с инструментами: их предмет уже
        # учтён (сами инструменты), а копия текста меряться не должна.
        # nashi-dorabotki.sh мерится ПЕРВЫМ учётом (запись uchyot-dorabotok), а не
        # собой: самоизмерение не сходится, доказано stend-atsiklichnosti.sh.
        case "$rel" in manifest.txt|nashi-dorabotki.sh|peredacha-*) continue ;; esac
        grep -qF "dorabotki/$rel|" "$MANIFEST" && continue
        case "$pary_ish" in *" $kat/$rel "*) continue ;; esac
        [ $n -eq 0 ] && echo "🔴 В КАТАЛОГЕ ЕСТЬ ФАЙЛЫ ВНЕ УЧЁТА — учёт о них не знает и не узнает:"
        n=$((n+1)); echo "   $rel"
    done < <(find "$kat" -mindepth 1 \( -name '.*' -o -name __pycache__ -o -name '*.bak-*' \
                 -o -name '*.SNYATO-*' -o -name 'SNYATO-*' \) -prune -o ! -type d -print0 | sort -z)
    if [ $n -gt 0 ]; then
        # 🔴 МЕХАНИЗМ ВМЕСТО ПАМЯТКИ. Записанное правило ведёт себя как незаписанное,
        # если ничто не заставляет к нему обратиться (замер 03.09.2026: урок про
        # готовность волокон лежал в памяти с 23.08 и не всплыл — искала по симптому).
        # Поэтому здесь стоит не «не забудь», а ГОТОВАЯ КОМАНДА.
        echo "   Новый инструмент? Спроси память ПО КЛАССУ ЗАДАЧИ, до того как поверишь прогону:"
        echo "     /opt/iskra/workspace/dorabotki/uroki-po-klassu подъём порча зрячесть сумма"
        echo "   и впиши файл в список внутри $0, иначе он останется невидимым."
    fi
    vne_bed=$n   # 🔴 с 26.09.2026: разряд влияет на код --check (был немым с 20.09 — печатал красное при коде 0)
    return 0
}

# ═══ НЕЗАКОММИЧЕННОЕ В ДЕРЕВЕ РЕПОЗИТОРИЯ ═══════════════════════════════════════
#
# 🔴 ЗАЧЕМ (06.09.2026, найдено случайно и дважды за один заход). Сжатие контекста
# обрывает работу БЕЗ СЛЕДА: правка остаётся в рабочем дереве — не в бою, не в коммите,
# без пробы. Версия в дереве и в бою при этом ОДНА, а код разный.
# Это «версия-призрак» НАОБОРОТ. Прежний класс — код в бою, которого нет в репозитории —
# ловится сверкой боя с деревом, и разряд для него у нас есть. Зеркальный не ловился НИЧЕМ:
# чтобы увидеть, надо посмотреть СОСТОЯНИЕ РЕПОЗИТОРИЯ, а такой проверки не было ни в одном
# приборе. За один заход так нашлись две брошенные работы: правка секретаря (оказалась
# пятой причиной потери знания, доведена и выпущена) и инструмент замера долга 118.
#
# ⚠️ ГРАНИЦЫ, названные здесь, а не в памятке:
#   · это НЕ отказ и на код возврата НЕ влияет: незакоммиченное — нормальное состояние
#     работы, красное на нём каждый заход перестанут читать вместе с настоящими находками;
#   · разряд смотрит ОДНО дерево (dsh-plugins). Другие репозитории им не проверяются;
#   · «чисто» здесь значит «нет незакоммиченного», а НЕ «всё выпущено» и не «всё в бою».
nezakommichennoe() {
    local kat="${UCHYOT_REPO:-/opt/iskra/workspace/dsh-plugins}" n spisok
    if [ ! -d "$kat/.git" ]; then
        echo "незакоммиченное в дереве: СЛЕПОТА — $kat не репозиторий (это «не смотрели», не «чисто»)"
        return 0
    fi
    spisok=$(cd "$kat" && git --no-optional-locks status --porcelain 2>/dev/null) || {   # A-N-823: под root git status переписывал .git/index владельцем root
        echo "незакоммиченное в дереве: СЛЕПОТА — git отказал (права? чужой владелец?)"
        return 0
    }
    n=$(printf '%s' "$spisok" | grep -c . )
    if [ "$n" -eq 0 ]; then
        echo "незакоммиченное в дереве: 0 (значит «нет несохранённого», НЕ «всё выпущено»)"
    else
        echo "⚠️ НЕЗАКОММИЧЕННОЕ В ДЕРЕВЕ: $n — работа, которую оборвёт следующее сжатие контекста:"
        printf '%s\n' "$spisok" | sed 's/^/     /'
        echo "     Довести до конца либо откатить осознанно. На код возврата НЕ влияет."
    fi
    return 0
}

