        fi
      done
      if [ "$mo_all$mo_any" = 11 ]; then
        rm -f "$tmp.now" "$tmp.diff"
        echo 'ОТЛОЖЕНО: только перечисленные суммы; это не совпадение с эталоном'
        exit 4
      fi
    fi
    echo "РАСХОЖДЕНИЙ НАЙДЕНО — что затёрто или изменено:"
    grep -E '^[-+][^-+]' "$tmp.diff"
    rm -f "$tmp.now" "$tmp.diff"
    exit 1
fi

echo "неизвестный режим: $MODE (ожидалось пусто, --check или --save)" >&2
exit 2
